// The word list.
//
// The words live in words.ts as one block-front-coded string, generated by
// tools/build-dictionary.mjs — see that file for the format and the numbers.
//
// There is deliberately no Set. This app only ever asks "is this a word?", and
// expanding 170,398 entries into a Set to answer that would cost roughly 240 ms
// of decoding at launch and about 20 MB of heap for the lifetime of the app.
// Binary search over the block-initial words, then a walk through the sixteen
// inside that block, answers the same question in under two microseconds and
// keeps nothing in memory but the packed string.
//
//   load        0.6 ms   (one split into 10,650 blocks)
//   lookup      1.7 us
//   heap        ~2 MB rather than ~20 MB
//
// Verified against the source list: all 170,398 words found, no false positives.

import { PACKED_WORDS } from "./words";

/** Split lazily — even 0.6 ms need not happen before the first frame. */
let blocks: string[] | null = null;
function getBlocks(): string[] {
  if (blocks === null) blocks = PACKED_WORDS.split("#");
  return blocks;
}

/** A block's first word is stored whole, so it reads without any decoding. */
function firstWord(block: string): string {
  const end = block.indexOf("!");
  return end < 0 ? block : block.slice(0, end);
}

export function isWord(raw: string): boolean {
  const word = raw.toLowerCase();
  if (!word) return false;
  const bs = getBlocks();

  // The last block whose first word is <= the target is the only one it can be in.
  let lo = 0;
  let hi = bs.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const first = firstWord(bs[mid]);
    if (first === word) return true;
    if (first < word) {
      found = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (found < 0) return false;

  // Walk it, rebuilding each word from the previous one's shared prefix.
  const parts = bs[found].split("!");
  let prev = parts[0];
  for (let i = 1; i < parts.length; i++) {
    const part = parts[i];
    prev = prev.slice(0, part.charCodeAt(0) - 48) + part.slice(1);
    if (prev === word) return true;
    if (prev > word) return false; // sorted: past the target, so it is not here
  }
  return false;
}
